-- The 183 Texas Exes chapters.
--
-- The scraper was fetching /contact-us for every chapter and that path now 404s
-- across the whole site. A non-200 was skipped without a word, so it reported
-- success while saving 14 of 184. Fixed to follow each chapter's leadership
-- page instead, which is where the contacts moved.
--
-- Upserts on dedupe_key, so re-running changes nothing and the sequence
-- columns — emailed, sequence_step, bounced, unsubscribed — are not touched.
-- Nothing you have already sent is forgotten.

on conflict (dedupe_key) do update set
  chapter_name = excluded.chapter_name,
  city         = coalesce(nullif(excluded.city, ''), public.chapter_leads.city),
  state        = coalesce(nullif(excluded.state, ''), public.chapter_leads.state),
  leader_name  = coalesce(nullif(excluded.leader_name, ''), public.chapter_leads.leader_name),
  email        = coalesce(nullif(excluded.email, ''), public.chapter_leads.email),
  source_url   = excluded.source_url,
  updated_at   = now();

-- What Texas looks like now.
select count(*) as chapters,
       count(email) as with_an_email,
       count(*) filter (where emailed) as already_emailed
from public.chapter_leads
where org = 'Texas';
